import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات برنامج الماجستير"
F=[]
def r(c,a,q1,q2,q3): F.append(("rule",[1],c,a,q1,q2,q3))
r("المادة 1 و2","تسمى هذه التعليمات «تعليمات برنامج الماجستير في جامعة العلوم والتكنولوجيا الأردنية»، ويعمل بها اعتباراً من بدء الفصل الدراسي الصيفي 2016/2017، وتسري على جميع الطلبة الملتحقين اعتباراً من تاريخ صدورها. والسنة الدراسية فصلان إجباريان مدة كل منهما ستة عشر أسبوعاً تشمل الامتحانات، وفصل صيفي اختياري مدته ثمانية أسابيع.","من أي فصل دراسي يعمل بتعليمات برنامج الماجستير وعلى من تسري؟","كم أسبوعاً مدة الفصل الدراسي والصيفي في برنامج الماجستير؟","متى بلشت تنطبق تعليمات الماجستير العامة؟")
r("المادة 5","تقدم طلبات الالتحاق ببرنامج الماجستير إلكترونياً، ولا يبت في أي طلب إلا إذا استوفى جميع الأوراق الثبوتية، ثم تحول إلى الكليات والأقسام المعنية للنظر والتنسيب بأسماء المرشحين حسب الشواغر إلى عمادة كلية الدراسات العليا لإعلان قوائم المقبولين.","كيف تقدم طلبات الالتحاق ببرنامج الماجستير؟","هل يبت في الطلب إذا كانت الأوراق الثبوتية ناقصة؟","كيف بقدم طلب ماجستير؟")
r("المادة 6 (د-ز)","يشترط أيضاً للقبول في الماجستير: تحقيق الشروط التي تقترحها لجنة القسم وتقرها لجنة الكلية (ويجوز أن تتضمن مساقات استدراكية)، وألا يكون الطالب قد فصل من التخصص الذي يتقدم إليه، واجتياز امتحان اللغة حسب قرارات وزارة التعليم العالي، وألا تكون صدرت بحقه عقوبة تأديبية لا تؤهله للقبول حسب رأي لجنة الدراسات العليا في الكلية.","هل يشترط امتحان اللغة للقبول في الماجستير؟","هل تمنع العقوبة التأديبية السابقة القبول في الماجستير؟","هل يقبل المفصول من نفس التخصص في الماجستير؟")
r("المادة 7","يتم قبول الطالب في الماجستير بقرار من العميد بناءً على توصية من لجنة القسم وتنسيب من لجنة الكلية، ويبلغ العميد القرار إلى الطالب والمسجل العام والكلية المعنية.","من يقرر قبول الطالب في الماجستير ومن يبلغ بالقرار؟","من يبلغ بقرار القبول في الماجستير؟","مين بقرر قبولي بالماجستير؟")
r("المادة 9 (أ)","يقبل تأجيل الطالب في الماجستير من العميد بناءً على توصية من لجنة القسم وتنسيب من لجنة الكلية، ويبلغ العميد القرار إلى الطالب والمسجل العام والكلية المعنية.","من يقبل طلب تأجيل الدراسة في الماجستير ومن يبلغ بالقرار؟","ما الإجراء لقبول التأجيل في الماجستير؟","مين بوافق على تأجيلي بالماجستير؟")
r("المادة 10 (أ)","تحسب مدة الانقطاع عن الدراسة بدون عذر مقبول في الماجستير من الحد الأعلى لمدة الدراسة أو التأجيل. وينبغي تقديم العذر قبل بداية الفصل الذي يلي فصل الانقطاع.","هل تحسب مدة الانقطاع من الحد الأعلى للدراسة في الماجستير؟","متى يقدم عذر الانقطاع في الماجستير؟","شو بصير بمدة انقطاعي؟")
r("المادة 10 (ب)","يبلغ عميد الكلية ورئيس القسم المعني والمسجل العام عند انسحاب طالب الماجستير من الجامعة بطلب إلكتروني، وتثبت ملاحظة (منسحب من الجامعة) في سجله الأكاديمي ويفقد مقعده.","من يبلغ عند انسحاب طالب الماجستير من الجامعة؟","هل يفقد الطالب مقعده عند الانسحاب من الجامعة في الماجستير؟","بدي أنسحب من الجامعة، شو بصير بسجلي؟")
r("المادة 10 (ج)","يجوز للطالب الفاقد لمقعده التقدم بطلب جديد: فإن قبل في نفس تخصصه والخطة التي قبل عليها سابقاً فعالة يحتفظ بسجله كاملاً (علاماته ومعدله ووضعه الأكاديمي) وتحسب مدته السابقة ضمن الحد الأعلى؛ وإن كانت الخطة غير فعالة أو مختلفة أو قبل في تخصص آخر تطبق عليه المادة 11 كطالب منتقل.","ماذا يحدث لسجل طالب الماجستير الفاقد لمقعده إذا أعيد قبوله في نفس التخصص؟","ماذا لو كانت الخطة التي قبل عليها سابقاً غير فعالة؟","فقدت مقعدي وبدي أرجع، علاماتي بتضل؟")
r("المادة 11 (ب)","يجوز الانتقال من مسار الرسالة إلى مسار الامتحان الشامل ضمن برنامج الماجستير وبالعكس بتوصية من مجلس القسم وتنسيب من لجنة الكلية وموافقة المجلس.","هل يجوز الانتقال بين مسار الرسالة ومسار الامتحان الشامل في الماجستير؟","من يوافق على الانتقال من مسار الرسالة إلى الشامل؟","بدي أحول من رسالة لشامل، كيف؟")
r("المادة 11 (ج، د)","يجوز انتقال الطالب من ماجستير في جامعة أخرى بعد تحقيق شروط القبول بقرار من العميد بتوصية لجنة القسم المنتقل إليه وتنسيب لجنة الكلية، ويجوز معادلة وإعفاء ما لا يتجاوز 9 ساعات بعلامة لا تقل عن B- ولا تدخل في المعدل التراكمي، ويحسم فصل مقابل 9 ساعات. ويتقدم الطالب بطلب احتساب المساقات للقسم خلال الشهر الأول بعد قبوله وتكون المعادلة خلال الفصل الأول لالتحاقه.","متى يقدم طلب احتساب المساقات بعد الانتقال في الماجستير؟","هل تدخل علامات المساقات المعادلة من جامعة أخرى في المعدل التراكمي في الماجستير؟","انتقلت من جامعة ثانية، متى بقدم طلب المعادلة؟")
r("المادة 12","يجوز السماح للطالب بدراسة ما لا يزيد عن 3 ساعات معتمدة من برامج ماجستير في جامعة أردنية أو جامعات أخرى معترف بها بعد قبوله وبموافقة العميد بتنسيب لجنة الكلية وتوصية لجنة القسم، ويعفى منها بشرط ألا تقل علامته عن B- ولا تدخل في معدله التراكمي، وألا يتجاوز مجموعها مع ساعات الانتقال 12 ساعة.","كم ساعة يجوز دراستها من جامعة أخرى بعد القبول في الماجستير؟","ما الحد الأدنى للعلامة وأقصى مجموع للساعات المحتسبة من خارج الجامعة في الماجستير؟","بقدر أدرس مادة بجامعة ثانية وأحسبها لي؟")
r("المادة 13 (ب-ه)","يسمح للطالب بتسجيل عدد ساعات أقل من الحد الأدنى في حالات مبررة بموافقة عميد الكلية والعميد. ويسمح بالانسحاب من مساق قبل بداية الامتحانات النهائية فيثبت بملاحظة (منسحب) ولا يدخل في النجاح والرسوب أو متطلبات التخرج، ولا يجوز الانسحاب من جميع المساقات إلا بعذر قهري يقبله العميد، فتكون دراسته لذلك الفصل مؤجلة ولا ترصد الرسوم، وإذا كان في الفصل الأول يعتبر منسحباً من الجامعة. وتلغى المنحة التشغيلية في ذلك الفصل.","هل يجوز تسجيل أقل من 6 ساعات في الماجستير؟","ماذا يحدث إذا انسحب طالب الماجستير من جميع المساقات في فصله الأول؟","ماذا يحدث للمنحة التشغيلية عند الانسحاب أو التأجيل؟")
r("المادة 14 (أ)","يدخل مدرس المساق الغياب على النظام الإلكتروني بشكل دوري خلال عشرة أيام من موعد الغياب ويمنع إدخال غياب لأي طالب مضى على محاضرته أكثر من عشرة أيام، ويبلغ الطالب إلكترونياً بشكل دوري. ومدرس المساق ورئيس القسم وعميد الكلية والعميد مسؤولون عن تنفيذ أحكام المواظبة.","خلال كم يوماً يدخل المدرس الغياب على النظام في الماجستير؟","من المسؤول عن تنفيذ أحكام المواظبة في الماجستير؟","متى بيدخل المدرس الغياب؟")
r("المادة 14 (ج)","إذا تجاوز غياب الطالب 20% في كافة المساقات يجوز له الانسحاب من جميع المساقات، وفي حال موافقة المجلس يعتبر منسحباً وتعتبر دراسته مؤجلة لذلك الفصل ولا ترصد الرسوم المدفوعة، ويبلغ إلكترونياً قبل الامتحانات النهائية، وخلاف ذلك يوضع له الرمز C (2.0) «محروم بسبب الغياب» لكافة المساقات وتدخل في معدله التراكمي.","ماذا يحدث إذا تجاوز غياب طالب الماجستير 20% في كافة المساقات؟","هل ترصد الرسوم المدفوعة عند الانسحاب من جميع المساقات بسبب الغياب؟","غبت أكثر من 20% بكل المواد، شو بصير؟")
r("المادة 15 (د، و)","العلامة النهائية لكل مساق في الماجستير هي مجموع علامات الامتحان النهائي والأعمال الفصلية، وقد تكون الامتحانات بعضها أو كلها أعمالاً تطبيقية أو تقارير أو بحوثاً، ويحدد مجلس القسم كيفية إجراء الامتحانات وتوزيع العلامات في بداية كل فصل. وعند قبول العذر يعقد امتحان تعويضي بالتنسيق خطياً مع رئيس القسم مكافئ بنوع الأسئلة ومستواها، ولا يجوز لصاحب (غير مكتمل) تأجيل دراسته إلا بعد إزالتها.","من يحدد كيفية الامتحانات وتوزيع العلامات في الماجستير؟","هل يجوز تأجيل الدراسة مع وجود (غير مكتمل) في الماجستير؟","كيف يكون الامتحان التعويضي في الماجستير؟")
r("المادة 16 (ب، ج، هـ)","المعدل التراكمي هو معدل علامات جميع المساقات التي درسها الطالب نجاحاً أو رسوباً ضمن الخطة حتى تاريخ حسابه، وإذا حصل على (غير مكتمل) يحسب معدله عند اكتمال العلامات وبأثر رجعي من حيث المراقبة أو الفصل. والمعدل الفصلي معدل مساقات ذلك الفصل، ويحسبان لأقرب منزلتين عشريتين.","كيف يحسب المعدل التراكمي والفصلي في الماجستير؟","إلى كم منزلة عشرية تحسب المعدلات في الماجستير؟","شو بصير بالمعدل لما يكون عندي غير مكتمل؟")
r("المادة 17 (ب-د)","على الطالب الموضوع تحت المراقبة إزالتها خلال فصلين دراسيين دون الصيفي. وللمراقبة بسبب إهمال الرسالة تعود إزالتها للمشرف بالكتابة إلى رئيس القسم وعميد الكلية وإبلاغ العميد والمسجل العام. ولا يجوز التسجيل لمساق الرسالة للموضوع تحت المراقبة بسبب انخفاض المعدل أو الرسوب في مساقين، ولا يجوز له التقدم للامتحان الشامل.","هل يجوز التقدم للامتحان الشامل وأنا تحت المراقبة في الماجستير؟","هل يجوز تسجيل مساق الرسالة وأنا تحت المراقبة؟","من يزيل المراقبة التي سببها إهمال الرسالة؟")
r("المادة 19 (أ/6-8، د)","يفصل الطالب كذلك إذا انطبقت عليه المادة 6/ب (مقبول) ولم يحقق شروط التحول إلى طالب نظامي، أو قرر المجلس أو لجنة المناقشة رسوبه، أو لم يتم المتطلبات ضمن الحد الأعلى للمدة. ويصدر قرار الفصل من مجلس العمداء بتنسيب من المجلس ويبلغ المسجل العام الطالب إلكترونياً أو خطياً على آخر عنوان له.","من يصدر قرار الفصل في الماجستير وكيف يبلغ الطالب؟","هل يفصل الطالب إذا لم يتحول إلى طالب نظامي بعد قبوله بتقدير مقبول؟","كيف بعرف إني انفصلت من الماجستير؟")
r("المادة 20 و21","الامتحان الشامل في الماجستير ذو طبيعة شاملة تكاملية يهدف إلى قياس قدرة الطالب على الربط بين المفاهيم الأساسية والمتقدمة وتوظيفها في حل المشكلات العلمية والتطبيقية في مجال تخصصه. وتنظمه وتدير شؤونه لجنة القسم.","ما هدف الامتحان الشامل في الماجستير؟","من ينظم الامتحان الشامل ويدير شؤونه في الماجستير؟","شو بقيس الامتحان الشامل؟")
r("المادة 23 (أ، ج)","في حال رسوب طالب الماجستير في الامتحان الشامل للمرة الثانية يفصل من البرنامج ويمنح شهادة الدبلوم العالي حسب المادة 19/ب. وتسجل نتيجة الامتحان الشامل في كشف العلامات بعبارة (ناجح) أو (راسب).","ماذا تسجل نتيجة الامتحان الشامل في كشف علامات الماجستير؟","ماذا يحدث عند الرسوب في الامتحان الشامل للمرة الثانية؟","رسبت بالشامل مرتين، شو بصير؟")
r("المادة 24 (6، 7، 9، 11)","من متطلبات منح درجة الماجستير: تسليم القسم وكلية الدراسات العليا ومكتبة الجامعة نسخة إلكترونية معتمدة من الرسالة ونسخة ورقية واحدة إلى المكتبة، وتقديم تفويض خطي بمنح الجامعة حرية التصرف في نشر الرسالة بحيث تعود حقوق الملكية الفكرية للجامعة، واجتياز امتحانات اللغة حسب تعليمات وزارة التعليم العالي، وتمنح شهادات التخرج عند استحقاقها في كل فصل دراسي.","كم نسخة من الرسالة تسلم ولمن في الماجستير؟","لمن تعود حقوق الملكية الفكرية لرسالة الماجستير؟","هل يشترط امتحان اللغة للتخرج من الماجستير؟")
r("المادة 25 (1)","للقسم أن يحدد لأي طالب عند قبوله دراسة مساقات استدراكية من مستوى البكالوريوس بما لا يزيد عن 9 ساعات معتمدة، لا تدخل نتائجها في المعدل التراكمي ولا ضمن متطلبات التخرج، يدرسها بنجاح خلال العام الجامعي الأول لالتحاقه، ولا تدخل مدة دراستها ضمن الحد الأعلى لمدة الدراسة.","كم ساعة استدراكية يحددها القسم عند القبول في الماجستير؟","هل تدخل المساقات الاستدراكية في المعدل أو الحد الأعلى لمدة الدراسة؟","بدخل المساق الاستدراكي بمعدلي؟")
r("المادة 25 (2)","للعميد السماح للطالب باستبدال مساق إجباري (غير مساقي الرسالة والامتحان الشامل) يستحيل تسجيله لعدم طرحه أو طرح مكافئه أو لوجود تعارض لا يمكن حله بمساق من مساقات الدراسات العليا بتوصية لجنة القسم وتنسيب لجنة الكلية، لمرة واحدة فقط خلال مدة الدراسة، بشروط: عدم طرح الأصلي ومكافئه في آخر فصلين، وأن تساوي ساعات البديل ساعات الأصلي أو تزيد، وألا يزيد تشابه محتواه مع مساقات الخطة عن 30%، وأن تخدم مخرجاته أهداف البرنامج.","هل يجوز استبدال مساق إجباري بمساق آخر في الماجستير وبأي شروط؟","كم مرة يسمح باستبدال مساق إجباري خلال الدراسة؟","ما أقصى نسبة تشابه للمساق البديل مع مساقات الخطة؟")
r("المادة 26 و27","تحتوي صفحة العنوان الأولى للرسالة على: عنوان الرسالة، واسم الطالب كما هو مسجل رسمياً، واسم المشرف والمشرف المشارك إن وجد، وعبارة «قدمت هذه الرسالة استكمالاً لمتطلبات الحصول على درجة الماجستير في كلية الدراسات العليا في جامعة العلوم والتكنولوجيا الأردنية» أو ما يعادلها بالإنجليزية، وتاريخ التقديم. والصفحة الثانية أسماء أعضاء لجنة المناقشة وتواقيعهم، والثالثة قائمة بالأوراق البحثية الناتجة عن الرسالة. وتقدم مطبوعة حسب الأسلوب المعتمد في كلية الدراسات العليا.","ماذا تحتوي صفحات العنوان الثلاث في رسالة الماجستير؟","حسب أي أسلوب تطبع رسالة الماجستير؟","شو لازم يكون بالصفحة الثالثة من الرسالة؟")
r("المادة 28","يقوم رئيس القسم بإرشاد وتوجيه الطلبة في سير دراستهم في برنامج الماجستير طيلة فترة دراسة كل منهم، وله أن يعين من أعضاء الهيئة التدريسية بالقسم من يساعد بالإرشاد لكل برنامج أو تخصص.","من يرشد ويوجه طلبة الماجستير في سير دراستهم؟","هل يجوز لرئيس القسم تعيين مساعد في الإرشاد؟","مين بوجهني بدراستي بالماجستير؟")
r("المادة 29 (ج، هـ)","يجوز تغيير المشرف لظروف خاصة تقبلها لجنة الكلية، وللمشرف اقتراح مشرف مشارك لا تقل رتبته عن أستاذ مساعد. ويجوز بقرار المجلس أن يستمر في الإشراف عضو هيئة التدريس المجاز أو المعار أو المنتدب شريطة قضاء ذلك داخل الأردن، وأن يشارك في الإشراف من غير العاملين في الجامعات من يحمل الدكتوراه ولديه خبرة عملية لا تقل عن 3 سنوات، وفي حال سفره خارج الأردن يجوز في حالات اضطرارية أن يستمر مشرفاً مشاركاً.","هل يجوز تغيير مشرف رسالة الماجستير؟","ماذا لو كان المشرف في إجازة أو إعارة خارج الأردن؟","هل يجوز أن يشارك في الإشراف شخص من خارج الجامعات؟")
r("المادة 30 (ب-د)","يقر المجلس موضوع الرسالة وخطة بحثها بناءً على تنسيب لجنة الكلية وتوصية لجنة القسم ويعلم عميد الكلية وعميد البحث العلمي، ويشترط إقرارهما قبل تقديم مشروع البحث إلى عمادة البحث العلمي. ويجوز تغيير موضوع الرسالة أو خطتها أو عنوانها بالطريقة التي أقر بها الموضوع والخطة أصلاً.","من يقر موضوع الرسالة وخطة بحثها في الماجستير؟","هل يجوز تغيير عنوان الرسالة بعد إقراره وكيف؟","بقدر أغير موضوع رسالتي؟")
r("المادة 31 (ج) و32 (ب)","يجوز في حالات اضطرارية استثناء المشرف المشارك من عضوية لجنة المناقشة إذا تعذر حضوره من خارج الأردن. ويحدد العميد موعد المناقشة بناءً على اقتراح المشرف وتوصية لجنة القسم وتنسيب لجنة الكلية بعد إنهاء الطالب جميع المتطلبات الأخرى، على أن يتم تنسيب لجنة الكلية قبل أسبوع على الأقل من التاريخ المقترح مرفقاً بتوصيات الأعضاء بجاهزية الرسالة.","من يحدد موعد مناقشة الرسالة في الماجستير؟","قبل كم من الوقت يتم تنسيب لجنة الكلية بموعد المناقشة؟","متى يستثنى المشرف المشارك من لجنة المناقشة؟")
r("المادة 32 (هـ) و33 (ج-هـ)","تقوم الكلية بالتنسيق مع وحدة العلاقات العامة بتصوير جلسة المناقشة. ويرفع المشرف قرار المناقشة موقعاً من اللجنة إلى رئيس القسم الذي يبلغه إلكترونياً إلى عميد الكلية والعميد والمسجل العام، ولا يثبت نجاح الطالب في سجله إلا بعد تسليم الرسالة في الفترة المحددة. وللمجلس تمديد التسليم مدة لا تزيد عن 4 أسابيع لمرة واحدة بطلب الطالب وموافقة المشرف، وتعديل قرار من لم يسلم في المدة إلى (راسب).","متى يثبت نجاح الطالب في المناقشة في سجله الأكاديمي في الماجستير؟","ماذا يحدث لمن لم يسلم الرسالة في المدة المحددة؟","هل تتصور الكلية جلسة المناقشة؟")
r("المادة 34-36","تتولى لجنة الدراسات العليا في الكلية: التنسيق بين الأقسام فيما يتعلق ببرنامج الدراسات العليا، والتنسيب إلى المجلس بإقرار موضوع وخطة بحث الرسالة بناءً على توصية لجنة القسم، وأي أمور يفوضها بها المجلس. ويبت مجلس العمداء في الإشكاليات الناشئة عن تطبيق التعليمات، ورئيس الجامعة والعميد وعمداء الكليات والمسجل العام مسؤولون عن تطبيقها.","ما صلاحيات لجنة الدراسات العليا في الكلية في برنامج الماجستير؟","من يبت في الإشكاليات الناشئة عن تطبيق تعليمات الماجستير؟","من المسؤول عن تطبيق تعليمات الماجستير؟")
